const {chromium}=require('/home/ubuntu/somi-build/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/home/ubuntu/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',args:['--no-sandbox','--disable-dev-shm-usage','--enable-webgl','--enable-unsafe-swiftshader','--use-angle=swiftshader']});
 const results=[],errors=[];
 const p=await browser.newPage({viewport:{width:440,height:980},deviceScaleFactor:1,isMobile:true,hasTouch:true});
 p.on('pageerror',e=>errors.push(e.message));
 await p.goto('https://setai.no/ksh/heimslig/3d-studio/?qa=20261102',{waitUntil:'domcontentloaded',timeout:30000});
 await p.waitForSelector('#r6-canvas canvas',{timeout:20000});
 await p.locator('.r6-tools [data-panel="furniture"]').click();
 await p.locator('#r6-add-type').selectOption('sofa');
 await p.locator('#r6-add').click();
 await p.waitForTimeout(500);
 const st=await p.evaluate(()=>{const s=JSON.parse(localStorage.getItem('ksh-room-v6'));return {items:s.items.map(i=>({type:i.type,x:i.x,z:i.z})),clashes:window.KSHRoom.collisions(s).length,outside:s.items.filter(i=>window.KSHRoom.outside(s,i)).length};});
 results.push({test:'Heimslig add furniture',...st});
 await p.locator('.r6-tools [data-panel="light"]').click();
 await p.locator('#r6-light-level').evaluate(el=>{el.value='1.35';el.dispatchEvent(new Event('input',{bubbles:true}));});
 await p.waitForTimeout(300);
 results.push({test:'Heimslig brightness',value:await p.evaluate(()=>JSON.parse(localStorage.getItem('ksh-room-v6')).lightStrength)});
 await p.locator('#r6-camera-view').selectOption('top');
 results.push({test:'Heimslig camera',value:await p.locator('#r6-camera-view').inputValue()});
 results.push({test:'Heimslig mobile width',...await p.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth}))});
 await p.screenshot({path:'/tmp/ksh-heimslig-interactive-440.png',fullPage:false});
 await p.goto('https://setai.no/ksh/flyt-gulv/?qa=20261102',{waitUntil:'domcontentloaded',timeout:30000});
 await p.waitForSelector('#net21-result .net21-card',{timeout:18000});
 await p.waitForTimeout(250);
 results.push({test:'Flyt journey',...await p.evaluate(()=>({selected:[...document.querySelectorAll('.net21-choices button')].filter(b=>b.getAttribute('aria-pressed')==='true').map(b=>b.textContent.trim()),summary:document.querySelector('.net21-result-head')?.textContent.trim().slice(0,140),buttons:document.querySelectorAll('.net21-card').length,modern:!!document.querySelector('link[href*="ksh-project-v25.css"]'),scroll:document.documentElement.scrollWidth,width:innerWidth}))});
 await p.locator('#prosjektveiviser').screenshot({path:'/tmp/ksh-flyt-v25-journey.png',timeout:18000});
 await p.goto('https://setai.no/ksh/heimdal-naturstein/3d-studio/?qa=20261102',{waitUntil:'domcontentloaded',timeout:30000});
 await p.waitForSelector('#stoneViewer .ksh25-stone-toolbar',{timeout:18000});
 await p.locator('#stoneViewer .ksh25-stone-toolbar input').evaluate(el=>{el.value='1.4';el.dispatchEvent(new Event('input',{bubbles:true}));});
 await p.waitForTimeout(250);
 results.push({test:'Heimdal stone slider',label:await p.locator('#stoneViewer .ksh25-stone-toolbar output').textContent(),full:await p.locator('#stoneViewer .ksh25-stone-toolbar button').count()});
 await p.locator('#stoneViewer').screenshot({path:'/tmp/ksh-heimdal-v25-stone.png',timeout:18000});
 results.push({test:'Page errors',errors:errors.slice(0,15)});
 console.log(JSON.stringify(results,null,2));
 await browser.close();
})().catch(e=>{console.error('QA ERROR',e.stack||e);process.exit(2)});
